// Generates features/collect/wf4-heal.json (credential names only, dummy chat id from .env.example).
const fs = require('fs');
const { randomUUID: id } = require('crypto');
const REPO = '/home/krishaanth/Desktop/personal_projects/github/prosus-hackathon';
const OUT = `${REPO}/features/collect/wf4-heal.json`;

const prev = fs.existsSync(OUT) ? JSON.parse(fs.readFileSync(OUT, 'utf8')) : { nodes: [] };
const prevNode = (name) => prev.nodes.find((n) => n.name === name) ?? {};

const pg = { postgres: { name: 'AirGuard Postgres' } };
const tg = { telegramApi: { name: 'AirGuard Telegram' } };
const set = (fields, extra = {}) => ({
  mode: 'manual',
  assignments: { assignments: Object.entries(fields).map(([name, value]) => ({ id: id(), name, value, type: 'string' })) },
  ...extra,
  options: {},
});
const pgInsert = (table) => ({
  schema: { __rl: true, mode: 'list', value: 'public' },
  table: { __rl: true, mode: 'name', value: table },
  columns: { mappingMode: 'autoMapInputData', value: {}, matchingColumns: [], schema: [] },
  options: {},
});
const rule = (leftValue, outputKey) => ({
  conditions: {
    options: { caseSensitive: true, leftValue: '', typeValidation: 'loose', version: 2 },
    conditions: [{ id: id(), leftValue, rightValue: '', operator: { type: 'boolean', operation: 'true', singleValue: true } }],
    combinator: 'and',
  },
  renameOutput: true,
  outputKey,
});
const telegram = (line, suffix = '') => ({
  chatId: "={{ $('Config').first().json.telegram_chat_id }}",
  text: `={{ '⚠️ AirGuard: ' + $('${line}').first().json.reason${suffix} }}`,
  additionalFields: { appendAttribution: false },
});

const WF = "($json.workflow.name.match(/WF\\d/) || [$json.workflow.name])[0]";
const ERR = '($json.execution || $json.trigger).error.message';
const RUN = '$json.body.resource';

const WATCHDOG_SQL = `-- Stale = newest real observation older than 15 min (the same window as the cell_status view).
-- The C11 test cells never count as fresh data. alarmed = the last watchdog line is ALERT DATA STALE.
select max(ts) as last_ts,
       floor(extract(epoch from now() - max(ts)) / 60)::int as age_min,
       coalesce(max(ts) < now() - interval '15 minutes', true) as stale,
       coalesce((select action = 'ALERT DATA STALE' from agent_log
                 where workflow = 'WF4' and action in ('ALERT DATA STALE', 'END STALE ALARM')
                 order by id desc limit 1), false) as alarmed
from observations
where cell_id not in ('89.5_178.5', '89.5_179.0', '89.5_179.5');`;

const nodes = [
  // three triggers → one Config → route by payload shape
  { name: 'Workflow failed', type: 'n8n-nodes-base.errorTrigger', typeVersion: 1, position: [0, 100], parameters: {} },
  { name: 'Apify run failed', type: 'n8n-nodes-base.webhook', typeVersion: 2, position: [0, 300],
    webhookId: prevNode('Apify run failed').webhookId ?? id(),
    parameters: { httpMethod: 'POST', path: 'airguard-apify-failed', responseMode: 'onReceived', options: {} } },
  { name: 'Every 5 min', type: 'n8n-nodes-base.scheduleTrigger', typeVersion: 1.2, position: [0, 500],
    parameters: { rule: { interval: [{ field: 'minutes', minutesInterval: 5 }] } } },
  { name: 'Config', type: 'n8n-nodes-base.set', typeVersion: 3.4, position: [240, 300],
    parameters: set({ telegram_chat_id: '123456789' }, { includeOtherFields: true }) },
  { name: 'Which trigger?', type: 'n8n-nodes-base.switch', typeVersion: 3.2, position: [460, 300],
    parameters: {
      rules: { values: [rule('={{ !!$json.workflow }}', 'workflow failed'), rule('={{ !!$json.body }}', 'apify run failed')] },
      options: { fallbackOutput: 'extra', renameFallbackOutput: 'watchdog' },
    } },

  // Error Trigger: some workflow that names WF4 as its error workflow failed
  { name: 'Failure line', type: 'n8n-nodes-base.set', typeVersion: 3.4, position: [700, 100],
    parameters: set({
      workflow: 'WF4',
      action: `={{ 'ALERT ' + ${WF}.toUpperCase() + ' FAILURE' }}`,
      reason: `={{ ${WF} + ' failed at node ' + ($json.execution ? $json.execution.lastNodeExecuted : 'trigger') + ': ' + String(${ERR}).slice(0, 300) }}`,
      outcome: "={{ 'alerted on Telegram' + ($json.execution && $json.execution.id ? ', execution ' + $json.execution.id : '') }}",
    }) },
  { name: 'Log failure', type: 'n8n-nodes-base.postgres', typeVersion: 2.5, position: [920, 100],
    parameters: pgInsert('agent_log'), credentials: pg },
  { name: 'Telegram failure', type: 'n8n-nodes-base.telegram', typeVersion: 1.2, position: [1140, 100],
    parameters: telegram('Failure line', " + ($('Config').first().json.execution ? '\\n' + $('Config').first().json.execution.url : '')"),
    credentials: tg },

  // Apify webhook: ACTOR.RUN.FAILED / ACTOR.RUN.TIMED_OUT
  { name: 'Apify failure line', type: 'n8n-nodes-base.set', typeVersion: 3.4, position: [700, 300],
    parameters: set({
      workflow: 'WF4',
      action: `={{ 'ALERT APIFY RUN ' + ${RUN}.status }}`,
      reason: `={{ 'Apify run ' + ${RUN}.id + ' ended ' + ${RUN}.status + ' at ' + ${RUN}.finishedAt + ': no data this cycle, the watchdog covers a longer gap' }}`,
      outcome: 'alerted on Telegram',
    }) },
  { name: 'Log Apify failure', type: 'n8n-nodes-base.postgres', typeVersion: 2.5, position: [920, 300],
    parameters: pgInsert('agent_log'), credentials: pg },
  { name: 'Telegram Apify failure', type: 'n8n-nodes-base.telegram', typeVersion: 1.2, position: [1140, 300],
    parameters: telegram('Apify failure line'), credentials: tg },

  // Watchdog: alarm once per stale period, log again when data is fresh
  { name: 'Check freshness', type: 'n8n-nodes-base.postgres', typeVersion: 2.5, position: [700, 540],
    parameters: { operation: 'executeQuery', query: WATCHDOG_SQL, options: {} }, credentials: pg },
  { name: 'Stale or fresh again?', type: 'n8n-nodes-base.switch', typeVersion: 3.2, position: [920, 540],
    parameters: {
      rules: { values: [rule('={{ $json.stale && !$json.alarmed }}', 'went stale'), rule('={{ !$json.stale && $json.alarmed }}', 'fresh again')] },
      options: {},
    } },
  { name: 'Stale line', type: 'n8n-nodes-base.set', typeVersion: 3.4, position: [1140, 480],
    parameters: set({
      workflow: 'WF4',
      action: 'ALERT DATA STALE',
      reason: "={{ $json.last_ts ? 'data stale ' + $json.age_min + ' min: every cell UNKNOWN, HOLD logic still active (newest observation ' + $json.last_ts + ')' : 'no observations yet: every cell UNKNOWN, HOLD logic still active' }}",
      outcome: 'alerted on Telegram',
    }) },
  { name: 'Log stale', type: 'n8n-nodes-base.postgres', typeVersion: 2.5, position: [1360, 480],
    parameters: pgInsert('agent_log'), credentials: pg },
  { name: 'Telegram stale', type: 'n8n-nodes-base.telegram', typeVersion: 1.2, position: [1580, 480],
    parameters: telegram('Stale line'), credentials: tg },
  { name: 'Fresh line', type: 'n8n-nodes-base.set', typeVersion: 3.4, position: [1140, 640],
    parameters: set({
      workflow: 'WF4',
      action: 'END STALE ALARM',
      reason: "={{ 'data fresh again: newest observation ' + $json.last_ts + ' (' + $json.age_min + ' min old)' }}",
      outcome: 'logged',
    }) },
  { name: 'Log fresh', type: 'n8n-nodes-base.postgres', typeVersion: 2.5, position: [1360, 640],
    parameters: pgInsert('agent_log'), credentials: pg },
].map((n) => ({ id: prevNode(n.name).id ?? id(), ...n }));

const link = (...targets) => ({ main: targets.map((t) => (t ? [].concat(t).map((node) => ({ node, type: 'main', index: 0 })) : [])) });
const connections = {
  'Workflow failed': link('Config'),
  'Apify run failed': link('Config'),
  'Every 5 min': link('Config'),
  Config: link('Which trigger?'),
  'Which trigger?': link('Failure line', 'Apify failure line', 'Check freshness'),
  'Failure line': link('Log failure'),
  'Log failure': link('Telegram failure'),
  'Apify failure line': link('Log Apify failure'),
  'Log Apify failure': link('Telegram Apify failure'),
  'Check freshness': link('Stale or fresh again?'),
  'Stale or fresh again?': link('Stale line', 'Fresh line'),
  'Stale line': link('Log stale'),
  'Log stale': link('Telegram stale'),
  'Fresh line': link('Log fresh'),
};

const wf = { name: 'AirGuard WF4 Heal', nodes, connections, settings: { executionOrder: 'v1' } };
fs.writeFileSync(OUT, JSON.stringify(wf, null, 2) + '\n');
console.log(`wrote ${OUT}: ${nodes.length} nodes`);

