      assert.equal(ref.id, undefined, `${n.name}: credential id removed`);
    }
  }
  for (const t of wf.nodes.filter((n) => TRIGGERS.includes(n.type))) assert.deepEqual(next(wf, t.name), ['Config'], `${t.name} → Config`);
