const fs = require('fs');
const base = process.env.N8N_BASE_URL.replace(/\/$/, '');
const flat = (o, p = '', out = {}) => { for (const [k, v] of Object.entries(o ?? {})) {
  const key = p ? `${p}.${k}` : k;
  if (v && typeof v === 'object' && !Array.isArray(v)) flat(v, key, out); else out[key] = JSON.stringify(v); } return out; };
(async () => {
  const [id, file, ...names] = process.argv.slice(2);
  const live = await (await fetch(`${base}/api/v1/workflows/${id}`, { headers: { 'X-N8N-API-KEY': process.env.N8N_API_KEY } })).json();
  const repo = JSON.parse(fs.readFileSync(file, 'utf8'));
  for (const name of names) {
    const l = flat(live.nodes.find((n) => n.name === name)), r = flat(repo.nodes.find((n) => n.name === name));
    const keys = [...new Set([...Object.keys(l), ...Object.keys(r)])].filter((k) => l[k] !== r[k] && !/credentials\..*\.id$/.test(k));
    console.log(`${name}: ` + keys.map((k) => `${k}: repo=${(r[k] ?? '-').slice(0, 70)} live=${(l[k] ?? '-').slice(0, 70)}`).join(' ;; '));
